getStage(c1) == Sprout && getStage(c2) == Sprout
end;

hint "watering does not affect empty cells"
test
let m = run(initModel, [WaterField, WaterField, WaterField]) in
let cell = getCell(m.field, 2, 2) in
!isPlanted(cell)
end;

